import AbstractView from '../../framework/view/abstract-view.js';

import {createModalSliderTemplate} from './modal-slider-template.js';
import ImageSlider from '../../utils/image-slider.js';

const createModalViewTemplate = ({title, description, price, authorPhoto, images}, isDeferred) =>
  `
    <div
      class="
        modal modal--product
        product-card-active
        is-active
      "
      data-modal="product-card"
      style="opacity: 0"
    >
      <div class="modal__wrapper">
        <div class="modal__overlay"></div>

        <div class="modal__content">
          <div class="modal-product">
            <button
              class="btn-close modal-product__btn-close"
              type="button"
              aria-label="Закрыть"
            >
              <svg width="55" height="56" aria-hidden="true">
                <use xlink:href="#icon-close-big"></use>
              </svg>
            </button>

            <svg
              class="
                modal-product__btn-close
                modal-product__loader
              "
              width="56"
              height="56"
              aria-hidden="true"
            >
              <use xlink:href="#icon-loader"></use>
            </svg>

            ${createModalSliderTemplate({authorPhoto, images})}

            <div class="product-description">
              <div class="product-description__header">
                <h3 class="title title--h2">${title}</h3>
                <b class="price price--size-big">
                  ${price}
                  <span>Р</span>
                </b>
              </div>

              <p class="text text--size-40">${description}</p>

              <button
                class="
                  btn
                  btn--outlined
                  btn--full-width
                  product-description__button
                "
                type="button"
                data-focus=""
              >
                ${isDeferred ? 'отложено' : 'отложить'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
 `;

/**
 * Представляет окно с подробной информацией о букете.
 * Создаёт слайдер изображений и предоставляет Presenter-у обработчики
 * закрытия и изменения статуса букета в отложенных.
 */
export default class ModalView extends AbstractView {
  #bouquet;
  #isDeferred = false;
  #slider = null;

  constructor(bouquet, isDeferred) {
    super();
    this.#bouquet = bouquet;
    this.#isDeferred = isDeferred;
  }

  get template() {
    return createModalViewTemplate(this.#bouquet, this.#isDeferred);
  }

  /** Инициализирует слайдер после добавления модального View в DOM. */
  initSlider() {
    const sliderElement = this.element.querySelector('.image-slider');

    this.#slider = new ImageSlider(sliderElement);
    this.#slider.init();
  }

  setCloseClickHandler = (callback) => {
    this._callback.closeClick = callback;
    this.element
      .querySelector('.modal-product__btn-close')
      .addEventListener('click', this.#closeClickHandler);
  };

  setDeferredClickHandler = (callback) => {
    this._callback.deferredClick = callback;
    this.element
      .querySelector('.product-description__button')
      .addEventListener('click', this.#deferredClickHandler);
  };

  updateDeferredStatus(isDeferred) {
    this.#isDeferred = isDeferred;

    const button = this.element.querySelector('.product-description__button');
    button.textContent = isDeferred ? 'отложено' : 'отложить';
  }

  #closeClickHandler = (evt) => {
    evt.preventDefault();
    this._callback.closeClick();
  };

  #deferredClickHandler = (evt) => {
    evt.preventDefault();
    this._callback.deferredClick();
  };

  /** Освобождает экземпляр Swiper, принадлежащий этому View. */
  destroy() {
    this.#slider?.destroy();
    this.#slider = null;
  }
}
