import AbstractView from '../../framework/view/abstract-view.js';

const createDeferredSumTemplate = ({productCount, sum}) =>
  `
    <div class="popup-deferred__sum">
      <p class="text text--total">Итого вы выбрали:</p>
      <div class="popup-deferred__block-wrap">
        <div class="popup-deferred__block">
          <p class="text text--total">Букеты</p>
          <span class="popup-deferred__count" data-attribute="count-defer">
            ${productCount}
          </span>
        </div>
        <div class="popup-deferred__block">
          <p class="text text--total">Сумма</p>
          <b class="price price--size-middle-p">
          ${sum}
          <span>Р</span></b>
        </div>
      </div>
    </div>
  `;

/**
 * Отображает агрегаты состояния отложенных: количество букетов
 * и общую сумму, переданные моделью.
 */
export default class DeferredSumView extends AbstractView {
  #deferred;

  constructor(deferred) {
    super();
    this.#deferred = deferred;
  }

  get template() {
    return createDeferredSumTemplate(this.#deferred);
  }
}

